    let n = str.length;
    let i = 0;
    let currentLen = 0;
    let maxLen = 0;
    let maxStartIndex = -1;

    while (i < n) {
        if (str[i] === ' ') {
            // End of a word: check if its length is even and greater than current max
            if (currentLen % 2 === 0) {
                if (maxLen < currentLen) {
                    maxLen = currentLen;
                    maxStartIndex = i - currentLen;
                }
