    let count = 0;
    for (let i = 0; i < n; i++) {
        if (i <= 1) continue;  // Skip 0 and 1 (not prime)
        let isPrime = true;
        for (let j = 2; j < i; j++) {
            if (i % j === 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) count++;
    }
    return count;
}
```

